// src/lib/mcp/tools/list-programs.ts
var list_programs_default = defineTool({
  name: "list_programs",
  title: "List yoga programs",
  description: "List the age-specific yoga programs offered by the studio (Kids, Teens, Adults, Seniors), with age range, duration, capacity and weekly timing.",
  inputSchema: {
    ageGroup: z.enum(["kids", "teens", "adults", "seniors"]).optional().describe("Optional age group to filter by.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ ageGroup }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated." }], isError: true };
    }
    const rows = ageGroup ? programs.filter((p) => p.id === ageGroup) : programs;
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { programs: rows }
    };
  }
});

// src/lib/mcp/tools/get-class-schedule.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var get_class_schedule_default = defineTool2({
  name: "get_class_schedule",
  title: "Get class schedule",
  description: "Get the weekly yoga class timetable: class name, time, audience, duration, instructor and available spots. Optionally filter by day and audience.",
  inputSchema: {
    day: z2.enum(weekDays).optional().describe("Optional day of the week, e.g. 'Monday'. Omit for the whole week."),
    audience: z2.string().trim().optional().describe("Optional audience filter, e.g. 'Kids', 'Teens', 'Adults', 'Seniors'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ day, audience }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated." }], isError: true };
    }
    const days = day ? [day] : [...weekDays];
    const result = days.map((d) => ({
      day: d,
      classes: schedule[d].filter(
        (c) => !audience || c.audience.toLowerCase().includes(audience.toLowerCase())
      )
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      structuredContent: { schedule: result }
    };
  }
});

// src/lib/mcp/tools/search-asanas.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^3.25.76";
var search_asanas_default = defineTool3({
  name: "search_asanas",
  title: "Search asana library",
  description: "Search the studio's asana (yoga pose) library by name, difficulty or category. Returns instructions, benefits and breathing cues.",
  inputSchema: {
    query: z3.string().trim().optional().describe("Free-text match against the Sanskrit name, English name or description."),
    difficulty: z3.enum(["Beginner", "Intermediate", "Advanced"]).optional().describe("Optional difficulty filter."),
    category: z3.string().trim().optional().describe("Optional category filter, e.g. 'Standing', 'Balance', 'Backbend', 'Resting'."),
    limit: z3.number().int().min(1).max(50).optional().describe("Maximum results, default 10.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, difficulty, category, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated." }], isError: true };
    }
    const q = query?.toLowerCase();
    const rows = asanas.filter((a) => !difficulty || a.difficulty === difficulty).filter((a) => !category || a.category.toLowerCase() === category.toLowerCase()).filter(
      (a) => !q || a.name.toLowerCase().includes(q) || a.english.toLowerCase().includes(q) || a.description.toLowerCase().includes(q)
    ).slice(0, limit ?? 10);
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { asanas: rows, count: rows.length }
    };
  }
});

